{%- assign mto_count = 0 -%}
{%- assign max_days = 0 -%}
{%- assign label = '' -%}
{%- for item in items -%}
  {%- if item.lead_days != nil -%}
    {%- if item.lead_days > 0 -%}
      {%- assign mto_count = mto_count | plus: 1 -%}
      {%- if item.lead_days > max_days -%}
        {%- assign max_days = item.lead_days -%}
      {%- endif -%}
      {%- assign safe_title = item.title | escape -%}
      {%- if label == '' -%}
        {%- assign label = safe_title -%}
      {%- elsif forloop.last -%}
        {%- assign label = label | append: ' and ' | append: safe_title -%}
      {%- else -%}
        {%- assign label = label | append: ', ' | append: safe_title -%}
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}
{%- if mto_count > 0 -%}
<div class="mto-lead"><p>Made to order: {{ label }}</p><p>Ships in {{ max_days }} {% if max_days == 1 %}day{% else %}days{% endif %}</p></div>
{%- endif -%}

